<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Что значит отказ казначейства в санкционировании?", "acceptedAnswer": {"@type": "Answer", "text": "Это возврат платёжного документа без исполнения, когда операция не прошла проверку ТОФК на соответствие контракту, целевому назначению и комплекту документов. Платёж нужно исправить и направить повторно."}}, {"@type": "Question", "name": "Какая самая частая причина отказа?", "acceptedAnswer": {"@type": "Answer", "text": "Отсутствие ИГК в документах и неверный код направления расходования целевых средств. На них приходится наибольшая доля возвратов."}}, {"@type": "Question", "name": "Где посмотреть причину отказа?", "acceptedAnswer": {"@type": "Answer", "text": "Причина указывается в протоколе, который казначейство формирует при возврате операции в «Электронном бюджете»."}}, {"@type": "Question", "name": "Что такое код направления расходования целевых средств?", "acceptedAnswer": {"@type": "Answer", "text": "Это код, определяющий статью затрат, на которую идёт платёж. Он должен быть прописан в сведениях об операциях и соответствовать назначению платежа и приложенным документам."}}, {"@type": "Question", "name": "Почему отказывают, если документы вроде правильные?", "acceptedAnswer": {"@type": "Answer", "text": "Частые причины — укрупнённый (недетализированный) код вместо нужного, отсутствие логической связи документа с контрактом, размытое назначение платежа или неактуальные сведения об операциях."}}, {"@type": "Question", "name": "Что делать, если казначейство вернуло платёж?", "acceptedAnswer": {"@type": "Answer", "text": "Установить причину по протоколу, исправить ошибку (код, документ, реквизит, сведения), при необходимости обновить сведения об операциях и направить платёж повторно."}}, {"@type": "Question", "name": "Можно ли вывести деньги с казначейского счёта на расчётный?", "acceptedAnswer": {"@type": "Answer", "text": "Свободно — нет. Перечисление возможно только в установленных случаях и порядке, после санкционирования; операции вне режима счёта казначейство не пропустит."}}, {"@type": "Question", "name": "Влияет ли раздельный учёт на санкционирование?", "acceptedAnswer": {"@type": "Answer", "text": "Да, особенно при расширенном казначейском сопровождении: казначейство сверяет фактические затраты с данными раздельного учёта. Ошибки в учёте повышают риск вопросов к операциям."}}, {"@type": "Question", "name": "Как снизить число отказов?", "acceptedAnswer": {"@type": "Answer", "text": "Проверять каждый платёж по чек-листу до отправки, держать актуальными сведения об операциях, заранее продлевать ЭП. При системных возвратах — провести аудит сопровождения."}}, {"@type": "Question", "name": "Кто помогает с санкционированием платежей?", "acceptedAnswer": {"@type": "Answer", "text": "Сопровождение операций можно передать на аутсорсинг: эксперт готовит и проверяет платежи, ведёт сведения и взаимодействует с ТОФК. Оставьте заявку — разберём вашу ситуацию."}}, {"@type": "Question", "name": "Почему казначейство вернуло или отклонило платёж?", "acceptedAnswer": {"@type": "Answer", "text": "Казначейство возвращает (отклоняет) платёж, когда документы не подтверждают целевой характер расхода: неверный код направления, отсутствует подтверждающий документ, расхождение с условиями контракта или со Сведениями об операциях. Это не штраф — после устранения замечаний платёж подаётся повторно."}}]}
